import type { IncomingMessage, ServerResponse } from "node:http";

import { StorageError } from "../storage/errors.js";
import { HandleRouteError, SendRestError } from "./errors.js";
import { HandleHealth } from "./routes/health.js";
import { HandleSessionHistory } from "./routes/history.js";
import { HandleListModels } from "./routes/models.js";
import { HandleCreatePile, HandleListPiles } from "./routes/piles.js";
import {
  HandleCreateSession,
  HandleGetSession,
  HandleListSessions,
} from "./routes/sessions.js";
import type { RouteContext } from "./routes/context.js";

export interface MatchedRoute
{
  pile?: string;
  sessionId?: string;
  history?: boolean;
}

function DecodePathSegment(segment: string): string
{
  try
  {
    return decodeURIComponent(segment);
  }
  catch
  {
    throw new StorageError("invalid_request", "route path is not valid");
  }
}

export function MatchApiRoute(pathname: string): MatchedRoute | null
{
  const segments = pathname.split("/").filter((segment) => segment.length > 0);

  if (segments.length < 2 || segments[0] !== "api")
  {
    return null;
  }

  if (segments.length === 2)
  {
    if (segments[1] === "health" || segments[1] === "models")
    {
      return {};
    }

    if (segments[1] === "piles")
    {
      return {};
    }

    return null;
  }

  if (segments[1] !== "piles" || segments.length < 3)
  {
    return null;
  }

  const pile = DecodePathSegment(segments[2]);

  if (segments.length === 3)
  {
    return { pile };
  }

  if (segments[3] !== "sessions")
  {
    return null;
  }

  if (segments.length === 4)
  {
    return { pile };
  }

  const sessionId = DecodePathSegment(segments[4]);

  if (segments.length === 5)
  {
    return { pile, sessionId };
  }

  if (segments.length === 6 && segments[5] === "history")
  {
    return { pile, sessionId, history: true };
  }

  return null;
}

export function ResolveApiEndpoint(pathname: string): string | null
{
  const segments = pathname.split("/").filter((segment) => segment.length > 0);

  if (segments.length < 2 || segments[0] !== "api")
  {
    return null;
  }

  if (segments.length === 2)
  {
    return segments[1] ?? null;
  }

  if (segments[1] === "piles")
  {
    if (segments[3] === "sessions")
    {
      if (segments.length === 4)
      {
        return "pile_sessions";
      }

      if (segments.length === 5)
      {
        return "pile_session";
      }

      if (segments.length === 6 && segments[5] === "history")
      {
        return "pile_session_history";
      }
    }
  }

  return null;
}

export async function DispatchApiRoute(
  context: RouteContext,
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
): Promise<void>
{
  const endpoint = ResolveApiEndpoint(url.pathname);

  if (endpoint === null)
  {
    SendRestError(response, 404, "not_found", "route not found");
    return;
  }

  const route = MatchApiRoute(url.pathname);

  if (route === null)
  {
    SendRestError(response, 404, "not_found", "route not found");
    return;
  }

  try
  {
    if (endpoint === "health")
    {
      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      HandleHealth(context, response);
      return;
    }

    if (endpoint === "models")
    {
      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      HandleListModels(context, response);
      return;
    }

    if (endpoint === "piles")
    {
      if (request.method === "GET")
      {
        await HandleListPiles(context, response);
        return;
      }

      if (request.method === "POST")
      {
        await HandleCreatePile(context, request, response);
        return;
      }

      SendRestError(response, 405, "method_not_allowed", "method not allowed");
      return;
    }

    if (endpoint === "pile_sessions")
    {
      if (route.pile === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method === "GET")
      {
        await HandleListSessions(context, route.pile, response);
        return;
      }

      if (request.method === "POST")
      {
        await HandleCreateSession(context, route.pile, request, response);
        return;
      }

      SendRestError(response, 405, "method_not_allowed", "method not allowed");
      return;
    }

    if (endpoint === "pile_session")
    {
      if (route.pile === undefined || route.sessionId === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      await HandleGetSession(context, route.pile, route.sessionId, response);
      return;
    }

    if (endpoint === "pile_session_history")
    {
      if (route.pile === undefined || route.sessionId === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      await HandleSessionHistory(
        context,
        route.pile,
        route.sessionId,
        url.searchParams,
        response,
      );
      return;
    }

    SendRestError(response, 404, "not_found", "route not found");
  }
  catch (error)
  {
    HandleRouteError(response, error);
  }
}

import { access, realpath } from "node:fs/promises";
import path from "node:path";

import { PathEscapeError } from "./errors.js";

export interface ResolveInputPathOptions
{
  allowMissing?: boolean;
}

export interface RootPolicy
{
  readonly rootDirectory: string;
  readonly canonicalRoot: string;
  ResolveInputPath(inputPath: string, options?: ResolveInputPathOptions): Promise<string>;
  ToRootRelativePath(absolutePath: string): string;
  AssertWithinRoot(absolutePath: string): void;
}

function NormalizeSeparators(inputPath: string): string
{
  return inputPath.replace(/\\/g, "/");
}

function HasParentTraversal(inputPath: string): boolean
{
  const segments = NormalizeSeparators(inputPath).split("/");

  for (const segment of segments)
  {
    if (segment === "..")
    {
      return true;
    }
  }

  return false;
}

function IsWithinRoot(candidate: string, canonicalRoot: string): boolean
{
  const relative = path.relative(canonicalRoot, candidate);

  if (relative === "")
  {
    return true;
  }

  if (relative.startsWith("..") || path.isAbsolute(relative))
  {
    return false;
  }

  return true;
}

export async function CreateRootPolicy(rootDirectory: string): Promise<RootPolicy>
{
  const canonicalRoot = await realpath(path.resolve(rootDirectory));

  function AssertWithinRoot(absolutePath: string): void
  {
    const normalized = path.resolve(absolutePath);

    if (!IsWithinRoot(normalized, canonicalRoot))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        normalized,
        "resolved_path_outside_root",
      );
    }
  }

  function ToRootRelativePath(absolutePath: string): string
  {
    const normalized = path.resolve(absolutePath);
    const relative = path.relative(canonicalRoot, normalized);

    if (relative === "" || relative === ".")
    {
      return ".";
    }

    if (relative.startsWith("..") || path.isAbsolute(relative))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        absolutePath,
        "resolved_path_outside_root",
      );
    }

    return relative.split(path.sep).join("/");
  }

  async function ResolveMissingWithinRoot(candidate: string): Promise<string>
  {
    AssertWithinRoot(candidate);

    let existingAncestor = canonicalRoot;
    let checkPath = candidate;
    const missingSegments: string[] = [];

    while (checkPath !== canonicalRoot && checkPath.length > canonicalRoot.length)
    {
      try
      {
        await access(checkPath);
        existingAncestor = await realpath(checkPath);
        AssertWithinRoot(existingAncestor);
        break;
      }
      catch
      {
        missingSegments.unshift(path.basename(checkPath));
        checkPath = path.dirname(checkPath);
      }
    }

    let resolved = existingAncestor;

    for (const segment of missingSegments)
    {
      resolved = path.join(resolved, segment);
      AssertWithinRoot(resolved);
    }

    return resolved;
  }

  async function ResolveInputPath(
    inputPath: string,
    options?: ResolveInputPathOptions,
  ): Promise<string>
  {
    if (!inputPath || inputPath.includes("\0"))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "invalid_path",
      );
    }

    const trimmed = inputPath.trim();

    if (trimmed.length === 0)
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "empty_path",
      );
    }

    if (HasParentTraversal(trimmed))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "parent_traversal",
      );
    }

    const normalizedInput = NormalizeSeparators(trimmed);
    let candidate: string;

    if (path.isAbsolute(normalizedInput))
    {
      candidate = path.resolve(normalizedInput);
    }
    else
    {
      candidate = path.resolve(canonicalRoot, normalizedInput);
    }

    if (!IsWithinRoot(candidate, canonicalRoot))
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "outside_root",
      );
    }

    if (options?.allowMissing)
    {
      return ResolveMissingWithinRoot(candidate);
    }

    const resolved = await realpath(candidate);
    AssertWithinRoot(resolved);
    return resolved;
  }

  return {
    rootDirectory: canonicalRoot,
    canonicalRoot,
    ResolveInputPath,
    ToRootRelativePath,
    AssertWithinRoot,
  };
}

import { stat } from "node:fs/promises";

import type { SheafChatConfig } from "../server/config.js";
import {
  AgentLifecycleState,
  type ModelMetadata,
  type ModelReference,
} from "../shared/types.js";
import {
  AllocateSessionShell,
  CreateStoragePaths,
  EnsurePileExists,
  type StoragePaths,
} from "../storage/index.js";
import { ResolveRootDirectory } from "../storage/paths.js";
import { StorageError } from "../storage/errors.js";

import { CreateSheafAuthStorage } from "./auth.js";
import {
  FormatSessionKey,
  LifecycleEmitter,
  type AgentStatusSnapshot,
  type ModelApplyTo,
  type SessionKey,
  type UserMessageSubmission,
} from "./lifecycle.js";
import {
  CreateSheafModelRegistry,
  ListModels,
  ModelValidationError,
  ValidateModelSelection,
  type SheafModelRegistryBundle,
} from "./models.js";
import {
  CreateSheafPiSession,
  type CreateSheafPiSessionInput,
  type PiSessionHandle,
} from "./piAdapter.js";
import {
  CreateRuntimeRecordFromColdResume,
  ResolvePileDirectoryPath,
  ResolveSessionBootstrap,
  SessionRuntime,
  type SessionRuntimeContext,
} from "./sessionRuntime.js";
import { CreateSessionSummarizer, type SessionSummaryGenerator } from "./summarizer.js";

export class AgentManagerError extends Error
{
  readonly code: string;

  constructor(code: string, message: string)
  {
    super(message);
    this.name = "AgentManagerError";
    this.code = code;
  }
}

export type CreatePiSessionFn = (
  input: CreateSheafPiSessionInput,
) => Promise<PiSessionHandle>;

export interface AgentManagerOptions
{
  config: SheafChatConfig;
  storagePaths?: StoragePaths;
  modelBundle?: SheafModelRegistryBundle;
  lifecycle?: LifecycleEmitter;
  summarizer?: SessionSummaryGenerator;
  createPiSession?: CreatePiSessionFn;
  idleOffloadSeconds?: number;
  setTimeoutFn?: typeof setTimeout;
  clearTimeoutFn?: typeof clearTimeout;
}

export interface CreateBlankSessionResult
{
  key: SessionKey;
  shell: import("../shared/types.js").AllocatedSessionShell;
}

export class AgentManager
{
  private readonly m_config: SheafChatConfig;
  private readonly m_storagePaths: StoragePaths;
  private readonly m_modelBundle: SheafModelRegistryBundle;
  private readonly m_lifecycle: LifecycleEmitter;
  private readonly m_createPiSession: CreatePiSessionFn;
  private readonly m_runtimeContext: SessionRuntimeContext;
  private readonly m_runtimes = new Map<string, SessionRuntime>();
  private readonly m_startupLocks = new Map<string, Promise<void>>();

  private constructor(
    config: SheafChatConfig,
    storagePaths: StoragePaths,
    modelBundle: SheafModelRegistryBundle,
    lifecycle: LifecycleEmitter,
    summarizer: SessionSummaryGenerator,
    createPiSession: CreatePiSessionFn,
    runtimeContext: SessionRuntimeContext,
  )
  {
    this.m_config = config;
    this.m_storagePaths = storagePaths;
    this.m_modelBundle = modelBundle;
    this.m_lifecycle = lifecycle;
    this.m_createPiSession = createPiSession;
    this.m_runtimeContext = runtimeContext;
  }

  static async Create(options: AgentManagerOptions): Promise<AgentManager>
  {
    const storagePaths = options.storagePaths ?? CreateStoragePaths(options.config.repoRoot);
    const authStorage = CreateSheafAuthStorage(options.config);
    const modelBundle =
      options.modelBundle ??
      await CreateSheafModelRegistry(options.config, authStorage);
    const lifecycle = options.lifecycle ?? new LifecycleEmitter();
    const summarizer = options.summarizer ?? CreateSessionSummarizer();
    const createPiSession = options.createPiSession ?? CreateSheafPiSession;
    const runtimeContext: SessionRuntimeContext = {
      config: options.config,
      storagePaths,
      lifecycle,
      summarizer,
      idleOffloadSeconds: options.idleOffloadSeconds ?? options.config.agentIdleOffloadSeconds,
      setTimeoutFn: options.setTimeoutFn ?? setTimeout,
      clearTimeoutFn: options.clearTimeoutFn ?? clearTimeout,
    };

    return new AgentManager(
      options.config,
      storagePaths,
      modelBundle,
      lifecycle,
      summarizer,
      createPiSession,
      runtimeContext,
    );
  }

  get lifecycle(): LifecycleEmitter
  {
    return this.m_lifecycle;
  }

  get storagePaths(): StoragePaths
  {
    return this.m_storagePaths;

    return this.m_storagePaths;
  }

  listModels(): ModelMetadata[]
  {
    return ListModels(
      this.m_config,
      this.m_modelBundle.modelRegistry,
      this.m_modelBundle.localProviderState,
    );
  }

  async createBlankSession(
    pile: string,
    rootDirectory: string,
    model: ModelReference,
  ): Promise<CreateBlankSessionResult>
  {
    await EnsurePileExists(this.m_storagePaths, pile);
    await this.ValidateRootDirectory(rootDirectory);
    ValidateModelSelection(
      this.m_config,
      this.m_modelBundle.modelRegistry,
      this.m_modelBundle.localProviderState,
      model,
    );

    const absoluteRoot = ResolveRootDirectory(this.m_storagePaths.repoRoot, rootDirectory);
    const shell = await AllocateSessionShell(
      this.m_storagePaths,
      pile,
      absoluteRoot,
      model,
    );

    return {
      key: {
        pile: shell.pile,
        sessionId: shell.sessionId,
      },
      shell,
    };
  }

  async attachSession(
    pile: string,
    sessionId: string,
    clientId?: string,
  ): Promise<AgentStatusSnapshot>
  {
    const key: SessionKey = { pile, sessionId };
    const encodedKey = FormatSessionKey(key);
    const existing = this.m_runtimes.get(encodedKey);

    if (existing !== undefined && existing.Record.piSession !== undefined)
    {
      existing.AttachClient(clientId);
      return this.BuildStatus(existing);
    }

    await this.RunWithStartupLock(encodedKey, async () =>
    {
      let runtime = this.m_runtimes.get(encodedKey);

      if (runtime !== undefined && runtime.Record.piSession !== undefined)
      {
        runtime.AttachClient(clientId);
        return;
      }

      runtime = await this.StartSessionRuntime(key);
      this.m_runtimes.set(encodedKey, runtime);
      runtime.AttachClient(clientId);
    });

    const runtime = this.m_runtimes.get(encodedKey);

    if (runtime === undefined)
    {
      throw new AgentManagerError("session_start_failed", "session runtime missing after startup");
    }

    return this.BuildStatus(runtime);
  }

  async submitUserMessage(key: SessionKey, message: UserMessageSubmission): Promise<void>
  {
    const runtime = await this.RequireActiveRuntime(key);
    await runtime.AcceptUserMessage(message);
  }

  async selectModel(
    key: SessionKey,
    model: ModelReference,
    applyTo: ModelApplyTo = "next_turn",
  ): Promise<void>
  {
    ValidateModelSelection(
      this.m_config,
      this.m_modelBundle.modelRegistry,
      this.m_modelBundle.localProviderState,
      model,
    );

    const runtime = await this.RequireActiveRuntime(key);
    await runtime.SelectModel(model, applyTo);
  }

  async cancelTurn(key: SessionKey): Promise<void>
  {
    const runtime = this.m_runtimes.get(FormatSessionKey(key));

    if (runtime === undefined)
    {
      return;
    }

    await runtime.CancelTurn();
  }

  markClientDetached(key: SessionKey, clientId?: string): void
  {
    const runtime = this.m_runtimes.get(FormatSessionKey(key));

    if (runtime === undefined)
    {
      return;
    }

    runtime.DetachClient(clientId);
  }

  getStatus(key: SessionKey): AgentStatusSnapshot | null
  {
    const runtime = this.m_runtimes.get(FormatSessionKey(key));

    if (runtime === undefined)
    {
      return null;
    }

    return this.BuildStatus(runtime);
  }

  async dispose(): Promise<void>
  {
    for (const runtime of this.m_runtimes.values())
    {
      runtime.Dispose();
    }

    this.m_runtimes.clear();
    this.m_startupLocks.clear();
  }

  private async RequireActiveRuntime(key: SessionKey): Promise<SessionRuntime>
  {
    const encodedKey = FormatSessionKey(key);
    let runtime = this.m_runtimes.get(encodedKey);

    if (runtime === undefined || runtime.Record.piSession === undefined)
    {
      await this.attachSession(key.pile, key.sessionId);
      runtime = this.m_runtimes.get(encodedKey);
    }

    if (runtime === undefined || runtime.Record.piSession === undefined)
    {
      throw new AgentManagerError("session_not_active", "session is not active");
    }

    return runtime;
  }

  private async StartSessionRuntime(key: SessionKey): Promise<SessionRuntime>
  {
    const bootstrap = await ResolveSessionBootstrap(
      this.m_storagePaths,
      key.pile,
      key.sessionId,
    );
    const record = CreateRuntimeRecordFromColdResume(key, bootstrap);
    const runtime = new SessionRuntime(this.m_runtimeContext, record);

    this.m_runtimes.set(FormatSessionKey(key), runtime);
    runtime.TransitionState(AgentLifecycleState.Starting);

    try
    {
      const piSession = await this.m_createPiSession({
        config: this.m_config,
        modelBundle: this.m_modelBundle,
        rootDirectory: bootstrap.rootDirectory,
        sessionFilePath: bootstrap.sessionFilePath,
        pileDirectory: ResolvePileDirectoryPath(this.m_storagePaths, key.pile),
        model: bootstrap.model,
        coldResume: bootstrap.manifest !== undefined,
      });

      runtime.BindPiSession(piSession);
      runtime.TransitionState(AgentLifecycleState.Active);
      return runtime;
    }
    catch (error)
    {
      const message = error instanceof Error ? error.message : String(error);
      runtime.TransitionState(AgentLifecycleState.Failed);
      runtime.ReportError({
        code: "session_start_failed",
        message,
        fatal: true,
      });
      throw new AgentManagerError("session_start_failed", message);
    }
  }

  private async ValidateRootDirectory(rootDirectory: string): Promise<void>
  {
    const absoluteRoot = ResolveRootDirectory(this.m_storagePaths.repoRoot, rootDirectory);

    try
    {
      const rootStat = await stat(absoluteRoot);

      if (!rootStat.isDirectory())
      {
        throw new AgentManagerError(
          "invalid_root_directory",
          `root directory is not a directory: ${rootDirectory}`,
        );
      }
    }
    catch (error)
    {
      if (error instanceof AgentManagerError)
      {
        throw error;
      }

      throw new AgentManagerError(
        "invalid_root_directory",
        `root directory does not exist: ${rootDirectory}`,
      );
    }
  }

  private BuildStatus(runtime: SessionRuntime): AgentStatusSnapshot
  {
    const record = runtime.Record;
    const piSession = record.piSession;

    return {
      key: record.key,
      state: record.state,
      model: record.model,
      rootDirectory: record.rootDirectory,
      connectedClientCount: runtime.ConnectedClientCount,
      manifestPresent: record.manifestWritten || record.manifest !== undefined,
      isStreaming: piSession?.isStreaming ?? false,
      activeRunCount: record.activeRunCount,
      activeToolCount: record.activeToolCount,
      manifest: record.manifest,
      provisionalRootDirectory: record.provisional?.rootDirectory,
      error: record.lastError,
    };
  }

  private RunWithStartupLock(encodedKey: string, operation: () => Promise<void>): Promise<void>
  {
    const previous = this.m_startupLocks.get(encodedKey) ?? Promise.resolve();
    let release!: () => void;
    const gate = new Promise<void>((resolve) =>
    {
      release = resolve;
    });
    const tail = previous.then(() => gate);
    this.m_startupLocks.set(encodedKey, tail);

    return previous
      .then(() => operation())
      .finally(() =>
      {
        release();
        if (this.m_startupLocks.get(encodedKey) === tail)
        {
          this.m_startupLocks.delete(encodedKey);
        }
      });
  }
}

export {
  AgentLifecycleState,
  ModelValidationError,
  StorageError,
};

import type { AgentManager } from "../../agents/manager.js";
import type { SheafChatConfig } from "../config.js";

export interface RouteContext
{
  config: SheafChatConfig;
  agentManager: AgentManager;
}

import { PathEscapeError } from "./errors.js";
import type { RootPolicy } from "./pathPolicy.js";
import type { ScopedToolContext, ToolAgentResult } from "./types.js";

export async function ResolveScopedPath(
  policy: RootPolicy,
  inputPath: string,
  options?: { allowMissing?: boolean },
): Promise<string>
{
  return policy.ResolveInputPath(inputPath, options);
}

export function HandlePathEscape(
  context: ScopedToolContext,
  toolName: string,
  error: unknown,
): ToolErrorResult | null
{
  if (!(error instanceof PathEscapeError))
  {
    return null;
  }

  context.audit.LogEscapeAttempt({
    inputPath: error.inputPath,
    reason: error.reason,
    tool: toolName,
  });

  return {
    content: [
      {
        type: "text" as const,
        text: `Path is outside the session root: ${error.inputPath}`,
      },
    ],
    details: { code: error.code, reason: error.reason },
    isError: true,
  };
}

export interface ToolErrorResult extends ToolAgentResult
{
  isError: true;
}

export function ToolError(message: string, details: Record<string, unknown> = {}): ToolErrorResult
{
  return {
    content: [{ type: "text" as const, text: message }],
    details,
    isError: true,
  };
}

export function ToolSuccess(text: string, details: Record<string, unknown> = {})
{
  return {
    content: [{ type: "text" as const, text }],
    details,
  };
}

const x_defaultMaxLines = 2000;
const x_defaultMaxBytes = 50 * 1024;

export function TruncateTextHead(text: string): {
  content: string;
  truncated: boolean;
  outputLines: number;
  totalLines: number;
}
{
  const lines = text.split("\n");
  const totalLines = lines.length;
  let outputLines = 0;
  let byteCount = 0;
  const selected: string[] = [];

  for (const line of lines)
  {
    const lineBytes = Buffer.byteLength(line, "utf-8") + (selected.length > 0 ? 1 : 0);

    if (selected.length >= x_defaultMaxLines)
    {
      break;
    }

    if (byteCount + lineBytes > x_defaultMaxBytes && selected.length > 0)
    {
      break;
    }

    selected.push(line);
    byteCount += lineBytes;
    outputLines += 1;
  }

  const truncated = outputLines < totalLines;

  return {
    content: selected.join("\n"),
    truncated,
    outputLines,
    totalLines,
  };
}

export function FormatNumberedLines(lines: string[], startLine: number): string
{
  const width = String(startLine + lines.length - 1).length;

  return lines
    .map((line, index) => {
      const lineNumber = String(startLine + index).padStart(width, " ");
      return `${lineNumber}|${line}`;
    })
    .join("\n");
}

export const x_treeDefaultIgnores = [
  "node_modules",
  ".git",
