import { realpath } from "node:fs/promises";
import path from "node:path";

import { GetDefaultSheafChatPaths } from "../server/repo_paths.js";
import { StorageError } from "./errors.js";
import { ValidatePileName, ValidateSessionId } from "./validation.js";

export const x_pilesDirRelative = "data/sheaf-chat/sessions/piles";
export const x_historyFileSuffix = ".sheaf-history.jsonl";
export const x_manifestFileSuffix = ".manifest.json";
export const x_provisionalFileSuffix = ".provisional.json";
export const x_sessionFileSuffix = ".jsonl";

export interface StoragePaths
{
  repoRoot: string;
  dataDir: string;
  sessionsDir: string;
  pilesDir: string;
}

export function CreateStoragePaths(repoRoot: string): StoragePaths
{
  const defaults = GetDefaultSheafChatPaths(repoRoot);

  return {
    repoRoot,
    dataDir: defaults.dataDir,
    sessionsDir: defaults.sessionsDir,
    pilesDir: path.join(defaults.sessionsDir, "piles"),
  };
}

export function ResolvePileDirectory(paths: StoragePaths, pile: string): string
{
  const validatedPile = ValidatePileName(pile);
  return path.join(paths.pilesDir, validatedPile);
}

export function ResolveSessionStem(paths: StoragePaths, pile: string, sessionId: string): string
{
  const pileDir = ResolvePileDirectory(paths, pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  return path.join(pileDir, validatedSessionId);
}

export function ResolveSessionFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_sessionFileSuffix}`;
}

export function ResolveManifestFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_manifestFileSuffix}`;
}

export function ResolveHistoryFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_historyFileSuffix}`;
}

export function ResolveProvisionalFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_provisionalFileSuffix}`;
}

export function ResolveRootDirectory(repoRoot: string, rootDirectory: string): string
{
  if (path.isAbsolute(rootDirectory))
  {
    return path.resolve(rootDirectory);
  }

  return path.resolve(repoRoot, rootDirectory);
}

# API Reference

Sheaf Chat exposes REST discovery and recovery endpoints plus one WebSocket route for live chat. All API routes are served by `projects/sheaf-chat/src/server/`.

## REST Errors

REST errors use this shape:

```json
{
  "error": {
    "code": "not_found",
    "message": "route not found"
  }
}
```

Known error codes include `invalid_request`, `invalid_json`, `invalid_pile`, `invalid_session_id`, `invalid_history_request`, `model_not_found`, `model_unavailable`, `invalid_root_directory`, `method_not_allowed`, `not_found`, `pile_not_found`, `manifest_not_found`, and `path_escape`.

## REST Endpoints

### `GET /api/health`

Returns service health, version, and non-secret dependency status.

```json
{
  "service": "sheaf-chat",
  "version": "0.1.0",
  "status": "ok",
  "dependencies": {
    "localInference": {
      "configured": true,
      "available": true
    },
    "openAi": {
      "configured": true
    }
  }
}
```

### `GET /api/piles`

Returns piles sorted by name.

```json
{
  "piles": [
    {
      "pile": "default",
      "sessionCount": 3,
      "latestUpdatedAt": "2026-06-08T00:00:00.000Z"
    }
  ]
}
```

### `POST /api/piles`

Creates a pile.

Request:

```json
{
  "pile": "default"
}
```

Response:

```json
{
  "pile": "default",
  "sessionCount": 0,
  "latestUpdatedAt": null
}
```

import { constants } from "node:fs";
import { access, readFile } from "node:fs/promises";

import { Type } from "typebox";

import { RelativizeDisplayPath } from "../results.js";
import type { ScopedToolContext, ScopedToolDefinition } from "../types.js";
import {
  FormatNumberedLines,
  HandlePathEscape,
  ResolveScopedPath,
  ToolError,
  ToolSuccess,
  TruncateTextHead,
} from "../toolHelpers.js";

const x_readSchema = Type.Object({
  path: Type.String({ description: "Path to the file to read (relative or absolute)" }),
  offset: Type.Optional(Type.Number({ description: "Line number to start reading from (1-indexed)" })),
  limit: Type.Optional(Type.Number({ description: "Maximum number of lines to read" })),
});

function IsBinaryBuffer(buffer: Buffer): boolean
{
  const sample = buffer.subarray(0, Math.min(buffer.length, 8192));

  for (const byte of sample)
  {
    if (byte === 0)
    {
      return true;
    }
  }

  return false;
}

export function CreateReadTool(context: ScopedToolContext): ScopedToolDefinition
{
  return {
    name: "read",
    label: "read",
    description:
      "Read the contents of a UTF-8 text file under the session root. Output is line-numbered and truncated to 2000 lines or 50KB. Use offset/limit for large files.",
    parameters: x_readSchema,
    async execute(_toolCallId, params, signal)
    {
      const pathArg = String(params.path ?? "");
      const offset = typeof params.offset === "number" ? params.offset : undefined;
      const limit = typeof params.limit === "number" ? params.limit : undefined;

      if (signal?.aborted)
      {
        return ToolError("Operation aborted");
      }

      let absolutePath: string;

      try
      {
        absolutePath = await ResolveScopedPath(context.policy, pathArg);
      }
      catch (error)
      {
        const escapeResult = HandlePathEscape(context, "read", error);

        if (escapeResult)
        {
          return escapeResult;
        }

        throw error;
      }

      const displayPath = RelativizeDisplayPath(context.policy, absolutePath);

      try
      {
        await access(absolutePath, constants.R_OK);
      }
      catch
      {
        return ToolError(`Could not read file: ${displayPath}`);
      }

      const buffer = await readFile(absolutePath);

      if (IsBinaryBuffer(buffer))
      {
        return ToolError(`File is not UTF-8 text: ${displayPath}`);
      }

      const textContent = buffer.toString("utf-8");
      const allLines = textContent.split("\n");
      const startLine = offset ? Math.max(0, offset - 1) : 0;

      if (startLine >= allLines.length)
      {
        return ToolError(
          `Offset ${offset} is beyond end of file (${allLines.length} lines total)`,
        );
      }

      let selectedLines: string[];

      if (limit !== undefined)
      {
        const endLine = Math.min(startLine + limit, allLines.length);
        selectedLines = allLines.slice(startLine, endLine);
      }
      else
      {
        selectedLines = allLines.slice(startLine);
      }

      const joined = selectedLines.join("\n");
      const truncation = TruncateTextHead(joined);
      const numbered = FormatNumberedLines(
        truncation.content.split("\n"),
        startLine + 1,
      );

      let output = `${displayPath}\n${numbered}`;

      if (truncation.truncated)
      {
        const nextOffset = startLine + truncation.outputLines + 1;
        output += `\n\n[Showing lines ${startLine + 1}-${startLine + truncation.outputLines} of ${allLines.length}. Use offset=${nextOffset} to continue.]`;
      }
      else if (limit !== undefined && startLine + selectedLines.length < allLines.length)
      {
        const nextOffset = startLine + selectedLines.length + 1;
        const remaining = allLines.length - (startLine + selectedLines.length);
        output += `\n\n[${remaining} more lines in file. Use offset=${nextOffset} to continue.]`;
      }

      return ToolSuccess(output, {
        path: displayPath,
        totalLines: allLines.length,
        truncated: truncation.truncated,
      });
    },
  };
}

